if (links.length !== 2) return false;

const mainLink = links[0];
const navLink = links[1];
const main = document.querySelector('main');
const nav = document.querySelector('nav');

if (!main || !nav) return false;
if (mainLink.getAttribute('href') !== '#' + main.id) return false;
if (navLink.getAttribute('href') !== '#' + nav.id) return false;

// When not focused, links are clipped / visually hidden
const rectMain = mainLink.getBoundingClientRect();
const rectNav = navLink.getBoundingClientRect();
if (rectMain.width > 1 || rectMain.height > 1) return false;
if (rectNav.width > 1 || rectNav.height > 1) return false;

