const container = document.getElementById('ai4a11y-skip-links');
const isEnabled = !!document.getElementById('ai4a11y-skip-links-styles');
if (!isEnabled) return true;
if (!container) return false;

const links = container.querySelectorAll('a');
const mainLink = links[0];
const navLink = links[1];

// 1. Main link checks
if (mainLink.tagName !== 'A') return false;
if (mainLink.textContent.trim() !== 'Skip to main content') return false;

mainLink.focus();
await new Promise(r => setTimeout(r, 60));
if (document.activeElement !== mainLink) return false;

const mainRect = mainLink.getBoundingClientRect();
if (mainRect.width < 24 || mainRect.height < 24 || mainRect.top < 0) return false;

const mainStyle = window.getComputedStyle(mainLink);
if (parseFloat(mainStyle.borderTopWidth) < 2 || mainStyle.borderTopStyle === 'none') return false;
if (mainStyle.backgroundColor !== 'rgb(255, 255, 255)') return false;

const topElMain = document.elementFromPoint(mainRect.left + mainRect.width / 2, mainRect.top + mainRect.height / 2);
if (topElMain !== mainLink) return false;

// 2. Nav link checks
if (navLink.tagName !== 'A') return false;
if (navLink.textContent.trim() !== 'Skip to navigation') return false;

navLink.focus();
await new Promise(r => setTimeout(r, 60));
if (document.activeElement !== navLink) return false;

const navRect = navLink.getBoundingClientRect();
if (navRect.width < 24 || navRect.height < 24 || navRect.top < 0) return false;

const navStyle = window.getComputedStyle(navLink);
if (parseFloat(navStyle.borderTopWidth) < 2 || navStyle.borderTopStyle === 'none') return false;
if (navStyle.backgroundColor !== 'rgb(255, 255, 255)') return false;

const topElNav = document.elementFromPoint(navRect.left + navRect.width / 2, navRect.top + navRect.height / 2);
if (topElNav !== navLink) return false;

document.activeElement.blur();
return true;

